#!/usr/bin/env python3
"""Fetch Paul Graham essays and generate an audiobook MP3."""

import html as html_lib
import json
import os
import re
import shutil
import subprocess
import tempfile
import urllib.error
import urllib.request


ESSAYS = [
    {
        "title": "Do Things that Don't Scale",
        "url": "https://paulgraham.com/ds.html",
    },
    {
        "title": "Founder Mode",
        "url": "https://paulgraham.com/foundermode.html",
    },
]

OUTPUT_PATH = "/root/audiobook.mp3"


def fetch_url(url: str) -> str:
    req = urllib.request.Request(
        url,
        headers={"User-Agent": "Mozilla/5.0 (Codex Audiobook)"},
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        charset = resp.headers.get_content_charset() or "utf-8"
        raw = resp.read()
        try:
            return raw.decode(charset, errors="ignore")
        except LookupError:
            return raw.decode("utf-8", errors="ignore")


def html_to_text(html: str) -> str:
    html = re.sub(r"(?is)<script.*?>.*?</script>", "", html)
    html = re.sub(r"(?is)<style.*?>.*?</style>", "", html)
    html = re.sub(r"(?i)<br\s*/?>", "\n", html)
    html = re.sub(r"(?i)</p>", "\n", html)
    html = re.sub(r"(?i)</li>", "\n", html)
    html = re.sub(r"(?i)</h\d>", "\n", html)
    text = re.sub(r"(?s)<[^>]+>", " ", html)
    text = html_lib.unescape(text)
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    return text.strip()


def clean_text_for_tts(text: str) -> str:
    text = text.replace("-->", "")
    text = re.sub(r"\[\s*\d+\s*\]", "", text)
    text = re.sub(r"http[s]?://\S+", "", text)

    lines = [line.strip() for line in text.splitlines()]
    filtered = []
    for line in lines:
        if not line:
            filtered.append("")
            continue
        lower = line.lower()
        if "translation" in lower:
            continue
        if "want to start a startup" in lower:
            continue
        filtered.append(line)

    text = "\n".join(filtered)
    text = re.sub(r"\n{3,}", "\n\n", text)
    # Flatten whitespace for smoother TTS
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def verify_content(text: str, expected_min_chars: int = 1000) -> bool:
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    if "summary" in text.lower()[:500] or "key points" in text.lower()[:500]:
        print("WARNING: Content appears to be a summary, not full text")
        return False
    return True


def chunk_text(text: str, max_chars: int) -> list:
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""

    for sentence in sentences:
        if not sentence:
            continue
        if len(sentence) > max_chars:
            if current:
                chunks.append(current.strip())
                current = ""
            for i in range(0, len(sentence), max_chars):
                chunks.append(sentence[i : i + max_chars])
            continue
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            chunks.append(current.strip())
            current = sentence + " "

    if current:
        chunks.append(current.strip())

    return chunks


def post_json(url: str, headers: dict, payload: dict) -> tuple:
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            return resp.status, resp.read(), None
    except urllib.error.HTTPError as exc:
        return exc.code, exc.read(), exc.reason
    except urllib.error.URLError as exc:
        return None, None, str(exc)


def concatenate_audio(audio_files: list, output_path: str, work_dir: str) -> bool:
    if not audio_files:
        return False

    list_file = os.path.join(work_dir, "audio_list.txt")
    with open(list_file, "w", encoding="utf-8") as handle:
        for audio_file in audio_files:
            handle.write(f"file '{audio_file}'\n")

    result = subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-f",
            "concat",
            "-safe",
            "0",
            "-i",
            list_file,
            "-c",
            "copy",
            output_path,
        ],
        capture_output=True,
        text=True,
    )

    if result.returncode != 0:
        print("ffmpeg failed:")
        print(result.stderr)
        return False

    return True


def create_with_elevenlabs(text: str, output_path: str) -> bool:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel
    chunks = chunk_text(text, max_chars=4500)

    temp_dir = tempfile.mkdtemp(prefix="audiobook_")
    audio_files = []

    try:
        for i, chunk in enumerate(chunks):
            chunk_file = os.path.join(temp_dir, f"chunk_{i:03d}.mp3")
            status, data, err = post_json(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json",
                    "Accept": "audio/mpeg",
                },
                payload={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
                },
            )

            if status != 200:
                print(f"ElevenLabs error: {status} {err or ''}")
                if data:
                    print(data.decode("utf-8", errors="ignore"))
                return False

            with open(chunk_file, "wb") as handle:
                handle.write(data)
            audio_files.append(chunk_file)

        return concatenate_audio(audio_files, output_path, temp_dir)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    chunks = chunk_text(text, max_chars=4000)
    temp_dir = tempfile.mkdtemp(prefix="audiobook_")
    audio_files = []

    try:
        for i, chunk in enumerate(chunks):
            chunk_file = os.path.join(temp_dir, f"chunk_{i:03d}.mp3")
            status, data, err = post_json(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json",
                    "Accept": "audio/mpeg",
                },
                payload={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx",
                    "response_format": "mp3",
                },
            )

            if status != 200:
                print(f"OpenAI TTS error: {status} {err or ''}")
                if data:
                    print(data.decode("utf-8", errors="ignore"))
                return False

            with open(chunk_file, "wb") as handle:
                handle.write(data)
            audio_files.append(chunk_file)

        return concatenate_audio(audio_files, output_path, temp_dir)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def create_with_gtts(text: str, output_path: str) -> bool:
    try:
        from gtts import gTTS
    except ImportError:
        print("gTTS is not installed and no API keys were found.")
        return False

    chunks = chunk_text(text, max_chars=4500)
    temp_dir = tempfile.mkdtemp(prefix="audiobook_")
    audio_files = []

    try:
        for i, chunk in enumerate(chunks):
            chunk_file = os.path.join(temp_dir, f"chunk_{i:03d}.mp3")
            tts = gTTS(text=chunk, lang="en", slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)

        return concatenate_audio(audio_files, output_path, temp_dir)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def create_audiobook(text: str, output_path: str) -> bool:
    if os.environ.get("ELEVENLABS_API_KEY"):
        print("Using ElevenLabs TTS")
        return create_with_elevenlabs(text, output_path)
    if os.environ.get("OPENAI_API_KEY"):
        print("Using OpenAI TTS")
        return create_with_openai(text, output_path)
    print("Using gTTS fallback")
    return create_with_gtts(text, output_path)


def main() -> int:
    all_text = []

    for essay in ESSAYS:
        print(f"Fetching: {essay['title']}")
        html = fetch_url(essay["url"])
        text = html_to_text(html)
        if not verify_content(text):
            print(f"WARNING: {essay['url']} may be incomplete")
        text = clean_text_for_tts(text)
        all_text.append(f"Essay: {essay['title']}. {text}")

    combined = "\n\n".join(all_text)
    print(f"Total text length: {len(combined)} characters")

    success = create_audiobook(combined, OUTPUT_PATH)
    if success:
        print(f"Audiobook created: {OUTPUT_PATH}")
        return 0

    print("Failed to create audiobook")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
